222	    /**
223	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
224	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
225	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
226	     * blank (e.g. {@code "   "}). The offending field names are reported through an
227	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
228	     * as a 400 response carrying an {@code errors} array of field names.
229	     *
230	     * @param ownerFieldsDto the submitted owner fields
231	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
232	     */
233	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
234	        List<String> blankFields = new ArrayList<>();
235	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
236	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
237	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
238	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
239	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
240	        if (!blankFields.isEmpty()) {
241	            throw new InvalidOwnerFieldsException(blankFields);
242	        }
243	    }
244	
245	    private void addIfBlank(List<String> blankFields, String field, String value) {
246	        if (value != null && value.isBlank()) {
247	            blankFields.add(field);
248	        }
249	    }
250	
251	    /**
252	     * Normalizes an owner's optional email address. When present it is stored and returned
253	     * lower-cased (using {@link Locale#ROOT} so normalization is locale-independent). A missing
254	     * (null) email is left as-is. Syntactic validity is enforced by Bean Validation ({@code @Email}
255	     * on {@link OwnerFieldsDto}), so an invalid address is already rejected as a 400 before this
256	     * method runs.
257	     *
258	     * @param email the raw email value from the request, or {@code null} when omitted
259	     * @return the lower-cased email, or {@code null} when none was supplied
260	     */
261	    private String normalizeEmail(String email) {
262	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
263	    }
264	
265	    /**
266	     * Rejects a create request whose normalized telephone is already used by any existing owner.
267	     * Existing owners' telephones are reduced to the same canonical form (via
268	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
269	     * only in formatting still collide. A collision is reported through a
270	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
271	     * as a 409 Conflict response.
272	     *
273	     * @param normalizedTelephone the canonical telephone of the owner being created
274	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
275	     */
276	    private void rejectDuplicateTelephone(String normalizedTelephone) {
277	        boolean duplicate = this.clinicService.findAllOwners().stream()
278	            .map(Owner::getTelephone)
279	            .filter(existing -> existing != null)
280	            .map(telephoneNormalizer::canonicalize)
281	            .anyMatch(normalizedTelephone::equals);
282	        if (duplicate) {
283	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
284	        }
285	    }
286	}
